CREATE OR REPLACE FUNCTION delete_player_match_session(p_match_id UUID, p_match_source TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN DELETE FROM match_motion_stats WHERE match_id = p_match_id AND match_source = p_match_source AND recorded_by = auth.uid(); DELETE FROM match_sensor_analytics WHERE match_id = p_match_id AND match_source = p_match_source AND player_id = auth.uid(); DELETE FROM match_health_data WHERE match_id = p_match_id AND match_source = p_match_source AND player_id = auth.uid(); DELETE FROM match_stroke_analytics WHERE match_id = p_match_id AND match_source = p_match_source AND processed_by = auth.uid(); DELETE FROM match_rally_stats WHERE match_id = p_match_id AND match_source = p_match_source AND player_id = auth.uid(); END; $$;